import{_ as n}from"./plugin-vue_export-helper-c27b6911.js";import{o as e,c as a,e as s}from"./app-4490560f.js";const t={},c=s(`<h1 id="tectonic-自包含的现代-tex-latex-引擎" tabindex="-1"><a class="header-anchor" href="#tectonic-自包含的现代-tex-latex-引擎" aria-hidden="true">#</a> tectonic（自包含的现代 TeX/LaTeX 引擎）</h1><blockquote><p>Homebrew 版本 0.15.0 ｜ 主页：见官方文档 ｜ 安装：<code>brew install tectonic</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>tectonic 是一个自包含（self-contained）、基于 WebAssembly 重构的现代 TeX/LaTeX 排版引擎。它把完整的一整套 TeX 发行版（包括全部宏包、字体、格式文件）打包进单个二进制中，并在首次编译时自动从网络拉取所需资源，彻底省去传统 TeX Live 那套庞大的安装与配置流程。</p><p>它主要解决传统 LaTeX 环境安装繁琐、依赖混乱、跨机器不一致的问题，适合用于自动化文档构建（CI/CD）、快速写论文/报告/简历，以及把排版能力嵌入到脚本或编程语言中。典型场景包括：在 GitHub Actions 里自动编译 PDF、用一条命令在无 TeX Live 的服务器上编译 LaTeX 文档。</p><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><p>通过 Homebrew 安装：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> tectonic

<span class="token comment"># 升级到最新版本</span>
brew upgrade tectonic

<span class="token comment"># 卸载</span>
brew uninstall tectonic
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>验证安装是否成功（应输出版本号 0.15.0）：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tectonic <span class="token parameter variable">--version</span>
<span class="token comment"># 输出示例：</span>
<span class="token comment"># tectonic 0.15.0</span>
<span class="token comment"># Copyright (C) 2016-2024 ...</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>查看帮助与子命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tectonic <span class="token parameter variable">--help</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>说明</th><th>示例</th></tr></thead><tbody><tr><td><code>tectonic FILE.tex</code></td><td>编译单个 LaTeX 文档为 PDF（最常用）</td><td><code>tectonic main.tex</code></td></tr><tr><td><code>tectonic --keep-logs FILE.tex</code></td><td>编译后保留日志文件</td><td><code>tectonic --keep-logs main.tex</code></td></tr><tr><td><code>tectonic -o out.pdf FILE.tex</code></td><td>指定输出 PDF 的文件名</td><td><code>tectonic -o report.pdf main.tex</code></td></tr><tr><td><code>tectonic --outdir DIR FILE.tex</code></td><td>指定输出目录</td><td><code>tectonic --outdir build main.tex</code></td></tr><tr><td><code>tectonic --print FILE.tex</code></td><td>输出文档正文（去排版）的文本</td><td><code>tectonic --print main.tex</code></td></tr><tr><td><code>tectonic --compile-all FILE.tex</code></td><td>完整编译（不跳过辅助文件/多次传递）</td><td><code>tectonic --compile-all thesis.tex</code></td></tr><tr><td><code>tectonic --help</code></td><td>显示全部选项</td><td><code>tectonic --help</code></td></tr><tr><td><code>tectonic --version</code></td><td>显示版本号</td><td><code>tectonic --version</code></td></tr><tr><td><code>tectonic --chatter minimal FILE.tex</code></td><td>减少输出信息（安静模式）</td><td><code>tectonic --chatter minimal main.tex</code></td></tr><tr><td><code>tectonic -X new NAME</code></td><td>创建带项目骨架的新文档目录</td><td><code>tectonic -X new thesis</code></td></tr><tr><td><code>tectonic -X init</code></td><td>在当前空目录初始化项目</td><td><code>tectonic -X init</code></td></tr><tr><td><code>tectonic -X watch</code></td><td>监听源文件变化自动编译</td><td><code>tectonic -X watch</code></td></tr><tr><td><code>tectonic -X build</code></td><td>在项目内按配置构建文档</td><td><code>tectonic -X build --open</code></td></tr><tr><td><code>tectonic -X bundle search KEY</code></td><td>在项目资源包中搜索文件</td><td><code>tectonic -X bundle search .bib</code></td></tr><tr><td><code>tectonic -X dump FILE</code></td><td>输出中间文件（aux/toc/log）</td><td><code>tectonic -X dump main.aux</code></td></tr><tr><td><code>tectonic -X show user-cache-dir</code></td><td>打印默认缓存目录路径</td><td><code>tectonic -X show user-cache-dir</code></td></tr></tbody></table><blockquote><p>说明：<code>-o</code> 与 <code>--outdir</code> 是 0.15.x 新引入的输出选项；旧版部分行为（如往 <code>tectonic_aux_files</code> 目录写中间文件）在新版本中已统一收敛到 <code>--outdir</code>/<code>--keep-logs</code> 等机制。<code>-X</code> 是 0.15 起的实验性子命令体系，详见文末 7.7 节。</p></blockquote><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-最小文档快速出-pdf" tabindex="-1"><a class="header-anchor" href="#示例-1-最小文档快速出-pdf" aria-hidden="true">#</a> 示例 1：最小文档快速出 PDF</h3><p>准备一个最小 LaTeX 文件：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 创建 main.tex</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> main.tex <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
\\documentclass{article}
\\begin{document}
Hello, Tectonic! This is a self-contained modern LaTeX engine.
\\end{document}
EOF</span>

<span class="token comment"># 编译（首次会自动下载缺失的宏包与格式文件）</span>
tectonic main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行后会生成 <code>main.pdf</code>。首次运行 tectonic 会在后台下载 <code>format</code> 与所需宏包并缓存到本地，之后再次编译即为纯离线、秒级完成。</p><h3 id="示例-2-生成带图片与公式的完整报告" tabindex="-1"><a class="header-anchor" href="#示例-2-生成带图片与公式的完整报告" aria-hidden="true">#</a> 示例 2：生成带图片与公式的完整报告</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token function">cat</span> <span class="token operator">&gt;</span> report.tex <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
\\documentclass[a4paper,11pt]{article}
\\usepackage{graphicx}
\\usepackage{amsmath}
\\begin{document}
\\section*{结果}

欧拉公式：
\\begin{equation}
e^{i\\pi} + 1 = 0
\\end{equation}

插图（假设存在 figure.png）：
\\begin{center}
\\includegraphics[width=0.5\\textwidth]{figure.png}
\\end{center}
\\end{document}
EOF</span>

<span class="token comment"># 指定输出文件名</span>
tectonic <span class="token parameter variable">-o</span> report.pdf report.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用 <code>\\usepackage{graphicx}</code>、<code>\\usepackage{amsmath}</code> 等常用宏包时无需手动安装，tectonic 会自动按需拉取。</p><h3 id="示例-3-用-print-提取纯文本内容" tabindex="-1"><a class="header-anchor" href="#示例-3-用-print-提取纯文本内容" aria-hidden="true">#</a> 示例 3：用 <code>--print</code> 提取纯文本内容</h3><p>用于快速核对文档正文或做全文检索：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tectonic <span class="token parameter variable">--print</span> report.tex
<span class="token comment"># 会输出去除了排版标记的纯文本，便于 grep 检索</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-在-ci-中自动化编译" tabindex="-1"><a class="header-anchor" href="#示例-4-在-ci-中自动化编译" aria-hidden="true">#</a> 示例 4：在 CI 中自动化编译</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 在 GitHub Actions / 本地脚本中一行搞定，无需安装 TeX Live</span>
tectonic <span class="token parameter variable">--outdir</span> dist --keep-logs main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>--outdir</code> 把产物集中到 <code>dist/</code>，配合 <code>--keep-logs</code> 保留编译日志便于排查错误。</p><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_5-1-使用-tectonictoml-配置文件" tabindex="-1"><a class="header-anchor" href="#_5-1-使用-tectonictoml-配置文件" aria-hidden="true">#</a> 5.1 使用 <code>.tectonictoml</code> 配置文件</h3><p>tectonic 支持在项目根目录放置 <code>Tectonic.toml</code> 或 <code>.tectonictoml</code> 文件来固化构建选项，之后直接 <code>tectonic</code> 即可按配置编译，无需每次敲一长串参数。这是一个真实的、开箱即用的最小配置：</p><div class="language-toml line-numbers-mode" data-ext="toml"><pre class="language-toml"><code><span class="token comment"># Tectonic.toml —— 放在项目根目录</span>
<span class="token punctuation">[</span><span class="token table class-name">files</span><span class="token punctuation">]</span>
<span class="token key property">default</span> <span class="token punctuation">=</span> <span class="token string">&quot;main.tex&quot;</span>        <span class="token comment"># 无参数运行 tectonic 时默认编译的文件</span>

<span class="token punctuation">[</span><span class="token table class-name">build</span><span class="token punctuation">]</span>
<span class="token key property">output_dir</span> <span class="token punctuation">=</span> <span class="token string">&quot;build&quot;</span>        <span class="token comment"># 产物与中间文件统一输出到 build/</span>
<span class="token key property">chatter</span> <span class="token punctuation">=</span> <span class="token string">&quot;minimal&quot;</span>         <span class="token comment"># 安静模式，减少日志噪音</span>
<span class="token key property">keep_logs</span> <span class="token punctuation">=</span> <span class="token boolean">true</span>            <span class="token comment"># 保留 .log 便于排查错误</span>
<span class="token key property">keep_aux_files</span> <span class="token punctuation">=</span> <span class="token boolean">false</span>      <span class="token comment"># 不保留 .aux/.toc/.bbl 等中间文件</span>
<span class="token key property">shell_escape</span> <span class="token punctuation">=</span> <span class="token boolean">false</span>        <span class="token comment"># 保持默认关闭，编译不可信文档更安全</span>
<span class="token key property">synctex</span> <span class="token punctuation">=</span> <span class="token boolean">true</span>              <span class="token comment"># 生成 SyncTeX 映射，配合编辑器反向定位</span>

<span class="token punctuation">[</span><span class="token table class-name">build.latex</span><span class="token punctuation">]</span>               <span class="token comment"># 可选：覆盖特定编译通道</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配置后即可在项目目录直接运行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 无需指定文件与参数，自动读取 Tectonic.toml</span>
tectonic
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>常用配置项一览：</p><table><thead><tr><th>配置键</th><th>类型</th><th>默认</th><th>说明</th></tr></thead><tbody><tr><td><code>[files] default</code></td><td>字符串</td><td>—</td><td>默认编译的入口文档</td></tr><tr><td><code>[files] exclude</code></td><td>数组</td><td><code>[]</code></td><td>明确排除的文件/目录</td></tr><tr><td><code>[build] output_dir</code></td><td>字符串</td><td><code>tectonic_aux_files</code></td><td>输出与中间文件目录</td></tr><tr><td><code>[build] chatter</code></td><td><code>minimal</code>/<code>default</code></td><td><code>default</code></td><td>日志详细程度</td></tr><tr><td><code>[build] keep_logs</code></td><td>布尔</td><td><code>false</code></td><td>是否保留 <code>.log</code></td></tr><tr><td><code>[build] keep_aux_files</code></td><td>布尔</td><td><code>false</code></td><td>是否保留 <code>.aux</code> 等中间文件</td></tr><tr><td><code>[build] shell_escape</code></td><td>布尔</td><td><code>false</code></td><td>是否允许 <code>\\write18</code> 执行外部命令</td></tr><tr><td><code>[build] synctex</code></td><td>布尔</td><td><code>false</code></td><td>是否生成 SyncTeX 数据</td></tr></tbody></table><blockquote><p>命令行参数优先级高于配置文件；<code>.tectonictoml</code> 与 <code>Tectonic.toml</code> 命名等价，若项目需同时兼容 windows/大小写敏感文件系统，统一使用 <code>Tectonic.toml</code>。</p></blockquote><h3 id="_5-2-环境变量详解" tabindex="-1"><a class="header-anchor" href="#_5-2-环境变量详解" aria-hidden="true">#</a> 5.2 环境变量详解</h3><p>tectonic 支持通过环境变量微调运行行为，适合在 CI、脚本或 Docker 中批量注入配置：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token builtin class-name">export</span> <span class="token assign-left variable">TECTONIC_CACHE_DIR</span><span class="token operator">=</span><span class="token string">&quot;<span class="token environment constant">$HOME</span>/.cache/tectonic&quot;</span>   <span class="token comment"># 缓存目录（宏包/格式文件）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TECTONIC_INPUT_DIR</span><span class="token operator">=</span><span class="token string">&quot;./src&quot;</span>                   <span class="token comment"># 额外输入搜索路径</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TECTONIC_OUTPUT_DIR</span><span class="token operator">=</span><span class="token string">&quot;./dist&quot;</span>                 <span class="token comment"># 默认输出目录（等价 --outdir）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TECTONIC_BIN_PATH</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token builtin class-name">command</span> <span class="token parameter variable">-v</span> tectonic<span class="token variable">)</span></span>&quot;</span>   <span class="token comment"># 二进制路径（供辅助工具定位）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TECTONIC_SHELL_ESCAPE</span><span class="token operator">=</span><span class="token string">&quot;false&quot;</span>                <span class="token comment"># 控制 shell 转义</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">TECTONIC_STARTUP_FILE</span><span class="token operator">=</span><span class="token string">&quot;&quot;</span>                     <span class="token comment"># 启动钩子脚本</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>TECTONIC_CACHE_DIR</code>：最常见。多台机器共享缓存可显著减少重复下载；CI 中把它挂到持久化缓存卷即可让每次构建近乎离线秒开。</li><li><code>TECTONIC_INPUT_DIR</code> / <code>TECTONIC_OUTPUT_DIR</code>：在脚本里统一重定向输入/输出，避免逐个参数传递。</li><li><code>TECTONIC_BIN_PATH</code>：供 <code>tectonic</code> 内置的一些自动化/辅助逻辑定位自身，一般无需手动设置。</li></ul><h3 id="_5-3-离线缓存预热与共享" tabindex="-1"><a class="header-anchor" href="#_5-3-离线缓存预热与共享" aria-hidden="true">#</a> 5.3 离线缓存预热与共享</h3><p>缓存是 tectonic 的核心优势所在。批量或 CI 构建前先做一次&quot;预热&quot;，把要用的格式与宏包全部下载齐全：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 预热：先编译一个覆盖常用宏包的最小文档</span>
<span class="token function">cat</span> <span class="token operator">&gt;</span> warmup.tex <span class="token operator">&lt;&lt;</span><span class="token string">&#39;EOF&#39;
\\documentclass{article}
\\usepackage{graphicx,amsmath,hyperref,geometry}
\\begin{document}warmup\\end{document}
EOF</span>
tectonic --compile-all warmup.tex

<span class="token comment"># 查看/确认缓存内容</span>
<span class="token function">ls</span> <span class="token parameter variable">-la</span> <span class="token string">&quot;<span class="token variable">\${TECTONIC_CACHE_DIR<span class="token operator">:-</span>$HOME<span class="token operator">/</span>Library<span class="token operator">/</span>Caches<span class="token operator">/</span>Tectonic}</span>&quot;</span>   <span class="token comment"># macOS</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>预热后删除 <code>warmup.pdf/.aux</code>，只保留缓存。在 CI 中把该目录打包上传为 artifact，或挂到 <code>actions/cache</code>，即可实现跨构建的离线快速编译。</p><h3 id="_5-4-多遍编译与交叉引用" tabindex="-1"><a class="header-anchor" href="#_5-4-多遍编译与交叉引用" aria-hidden="true">#</a> 5.4 多遍编译与交叉引用</h3><p>tectonic 默认采用&quot;按需多遍&quot;策略，但对涉及目录（<code>.toc</code>）、引用（<code>\\ref</code>）、索引（<code>\\index</code>）和文献的文档，交叉引用编号需要多遍传递才能收敛正确。强制完整多遍：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 强制完整编译（含多遍 + 书目），保证 \\ref、目录、参考文献编号正确</span>
tectonic --compile-all thesis.tex

<span class="token comment"># 也可结合 --outdir 把中间文件隔离</span>
tectonic --compile-all <span class="token parameter variable">--outdir</span> build thesis.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-5-书目管理-bibtex" tabindex="-1"><a class="header-anchor" href="#_5-5-书目管理-bibtex" aria-hidden="true">#</a> 5.5 书目管理（BibTeX）</h3><p><strong>tectonic 内置了对经典 BibTeX（<code>.bib</code> + <code>\\bibliography</code>）的原生支持</strong>，无需外部 <code>bibtex</code> 程序：</p><div class="language-tex line-numbers-mode" data-ext="tex"><pre class="language-tex"><code><span class="token comment">% 在正文中引用，文末列出书目</span>
<span class="token function selector">\\documentclass</span><span class="token punctuation">{</span><span class="token keyword">article</span><span class="token punctuation">}</span>
<span class="token function selector">\\begin</span><span class="token punctuation">{</span><span class="token keyword">document</span><span class="token punctuation">}</span>
在文中引用 <span class="token function selector">\\cite</span><span class="token punctuation">{</span><span class="token keyword">knuth1984</span><span class="token punctuation">}</span>。

<span class="token function selector">\\bibliographystyle</span><span class="token punctuation">{</span>plain<span class="token punctuation">}</span>
<span class="token function selector">\\bibliography</span><span class="token punctuation">{</span>refs<span class="token punctuation">}</span>   <span class="token comment">% 对应 refs.bib</span>
<span class="token function selector">\\end</span><span class="token punctuation">{</span><span class="token keyword">document</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 使用 --compile-all 让 tectonic 自动完成 &quot;编译→BibTeX→再编译&quot; 的多遍流程</span>
tectonic --compile-all <span class="token parameter variable">--outdir</span> build main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>注意 <code>.bib</code> 文件应放在输入搜索路径内（默认当前目录，或用 <code>TECTONIC_INPUT_DIR</code> 指向）。</p><h3 id="_5-6-大项目组织-多章节拆分与主文档管理" tabindex="-1"><a class="header-anchor" href="#_5-6-大项目组织-多章节拆分与主文档管理" aria-hidden="true">#</a> 5.6 大项目组织：多章节拆分与主文档管理</h3><p>对论文、报告、书籍等大型项目，务必按章节拆分文件并用主文档统一管理。tectonic 直接支持标准 LaTeX 的拆分机制：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 推荐的项目结构</span>
book/
├── Tectonic.toml          <span class="token comment"># 配置文件</span>
├── main.tex               <span class="token comment"># 主文档（入口）</span>
├── chapters/
│   ├── intro.tex
│   ├── methods.tex
│   └── results.tex
├── refs.bib               <span class="token comment"># 书目库</span>
└── figures/
    └── fig1.pdf
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>主文档 <code>main.tex</code>：</p><div class="language-tex line-numbers-mode" data-ext="tex"><pre class="language-tex"><code><span class="token function selector">\\documentclass</span><span class="token punctuation">[</span>11pt<span class="token punctuation">]</span><span class="token punctuation">{</span><span class="token keyword">book</span><span class="token punctuation">}</span>
<span class="token function selector">\\usepackage</span><span class="token punctuation">{</span><span class="token keyword">graphicx</span><span class="token punctuation">}</span>
<span class="token function selector">\\begin</span><span class="token punctuation">{</span><span class="token keyword">document</span><span class="token punctuation">}</span>
<span class="token function selector">\\frontmatter</span>
<span class="token function selector">\\tableofcontents</span>            <span class="token comment">% 生成目录（需多遍编译）</span>

<span class="token function selector">\\mainmatter</span>
<span class="token comment">% \\input 直接把各章内容并入，适合较小的章节</span>
<span class="token function selector">\\input</span><span class="token punctuation">{</span>chapters/intro<span class="token punctuation">}</span>
<span class="token function selector">\\input</span><span class="token punctuation">{</span>chapters/methods<span class="token punctuation">}</span>
<span class="token comment">% \\include 另起一页，配合 \\includeonly 可只编译单章调试</span>
<span class="token function selector">\\include</span><span class="token punctuation">{</span>chapters/results<span class="token punctuation">}</span>

<span class="token function selector">\\backmatter</span>
<span class="token function selector">\\bibliographystyle</span><span class="token punctuation">{</span>plain<span class="token punctuation">}</span>
<span class="token function selector">\\bibliography</span><span class="token punctuation">{</span>refs<span class="token punctuation">}</span>
<span class="token function selector">\\end</span><span class="token punctuation">{</span><span class="token keyword">document</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong><code>\\input</code></strong>：相当于把文件内容原地粘贴进来，不换页，适合小节。</li><li><strong><code>\\include</code></strong>：每章独立成页，并维护章节级 <code>.aux</code>；配合 <code>\\includeonly</code> 可单独调试一章，显著加快大文档编译：</li></ul><div class="language-tex line-numbers-mode" data-ext="tex"><pre class="language-tex"><code><span class="token function selector">\\includeonly</span><span class="token punctuation">{</span>chapters/results<span class="token punctuation">}</span>   <span class="token comment">% 只编译 results 章，其余占位</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>各章节文件<strong>不要</strong>写 <code>\\documentclass</code> 与 <code>\\begin{document}</code>，只写正文内容。</li><li>多章大文档务必加 <code>--compile-all</code>，否则目录和交叉引用编号会错误。</li></ul><h3 id="_5-7-与编辑器搭配" tabindex="-1"><a class="header-anchor" href="#_5-7-与编辑器搭配" aria-hidden="true">#</a> 5.7 与编辑器搭配</h3><p>tectonic 无状态、单命令，非常适合接入编辑器与文件监听：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># VS Code：LaTeX Workshop 插件的 settings.json 中</span>
<span class="token comment"># &quot;latex-workshop.latex.recipe&quot; 指向 tectonic，或用 watchexec 手动监听</span>
watchexec <span class="token parameter variable">-w</span> main.tex <span class="token parameter variable">-w</span> chapters tectonic <span class="token parameter variable">--outdir</span> build main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>生成 SyncTeX 后（<code>[build] synctex = true</code>），配合支持 SyncTeX 的编辑器可实现「PDF 与源码双向定位」。</p><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><h3 id="_6-1-书目相关的坑" tabindex="-1"><a class="header-anchor" href="#_6-1-书目相关的坑" aria-hidden="true">#</a> 6.1 书目相关的坑</h3><ul><li><strong>tectonic 不支持 biblatex / biber</strong>。biber 是独立的外部程序，tectonic 出于安全与自包含原则<strong>不会调用外部可执行文件</strong>，因此 <code>\\usepackage{biblatex}</code> + <code>\\addbibresource</code> 会报错或无法生成参考文献。<strong>请改用经典 BibTeX 流程</strong>（<code>\\bibliography</code> + <code>\\bibliographystyle</code>，见 5.5 节）。</li><li>忘记加 <code>--compile-all</code> 时，书目/目录会&quot;不刷新&quot;，表现为引用编号为 <code>??</code> 或目录为空——先补上 <code>--compile-all</code>。</li></ul><h3 id="_6-2-中文与字体问题" tabindex="-1"><a class="header-anchor" href="#_6-2-中文与字体问题" aria-hidden="true">#</a> 6.2 中文与字体问题</h3><p>tectonic 底层基于 XeTeX，中文排版需用 <code>ctex</code> 宏包（内部走 xeCJK），并依赖<strong>系统字体</strong>：</p><div class="language-tex line-numbers-mode" data-ext="tex"><pre class="language-tex"><code><span class="token function selector">\\documentclass</span><span class="token punctuation">{</span><span class="token keyword">ctexart</span><span class="token punctuation">}</span>   <span class="token comment">% 或 \\usepackage{ctex}</span>
<span class="token function selector">\\begin</span><span class="token punctuation">{</span><span class="token keyword">document</span><span class="token punctuation">}</span>
你好，Tectonic！
<span class="token function selector">\\end</span><span class="token punctuation">{</span><span class="token keyword">document</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>macOS 用 CoreText、Linux 用 fontconfig 读取系统字体；容器/CI 里若提示缺字体，需先 <code>apt install fonts-noto-cjk</code> 之类的 CJK 字体包。</li><li>中文字体缺失会报 &quot;font not found&quot; 类错误，检查系统字体后再编译。</li></ul><h3 id="_6-3-常见报错与解决" tabindex="-1"><a class="header-anchor" href="#_6-3-常见报错与解决" aria-hidden="true">#</a> 6.3 常见报错与解决</h3><table><thead><tr><th>报错/现象</th><th>常见原因</th><th>解决办法</th></tr></thead><tbody><tr><td><code>could not find package</code></td><td>宏包不在内置集合（个别冷门/古老宏包）</td><td>换等价宏包，或自行改用内置版本</td></tr><tr><td>网络错误 <code>TLS</code>/<code>404</code></td><td>首次拉取资源失败</td><td>检查网络/代理，设 <code>https_proxy</code>，或先预热缓存</td></tr><tr><td>引用显示 <code>??</code></td><td>未多遍编译</td><td>加 <code>--compile-all</code></td></tr><tr><td><code>font not found</code></td><td>系统缺中文字体</td><td>安装 CJK 字体（如 noto-cjk）</td></tr><tr><td><code>biber</code>/<code>biblatex</code> 相关报错</td><td>用了不受支持的 biblatex</td><td>改回经典 BibTeX 流程</td></tr><tr><td><code>Output file ... is not valid</code></td><td>编译中途崩溃/磁盘写满</td><td>清理 <code>--outdir</code> 残留中间文件后重试</td></tr><tr><td>文件路径含空格/中文</td><td>部分内部工具对路径敏感</td><td>项目路径尽量用 ASCII 无空格，或用 <code>--outdir</code> 收拢产物</td></tr></tbody></table><h3 id="_6-4-性能与安全注意点" tabindex="-1"><a class="header-anchor" href="#_6-4-性能与安全注意点" aria-hidden="true">#</a> 6.4 性能与安全注意点</h3><ul><li><strong>性能</strong>：大文档首次编译（含格式加载 + 预热下载）有一次固定开销，先预热缓存；tectonic 缓存格式/宏包后，增量编译通常远快于传统 TeX Live 冷启动。超大项目用 <code>\\includeonly</code> 单章调试可再提速。</li><li><strong>安全（重要）</strong>：tectonic 支持 shell 转义（<code>\\write18</code>），但<strong>默认禁用</strong>。编译来自不可信来源的 <code>.tex</code>（网上下载的模板、他人邮件附件）时，务必保持 <code>shell_escape = false</code>，防止文档内嵌的 <code>\\write18{...}</code> 在机器上执行任意系统命令。</li><li>除非确有必要，不要在公开 CI/共享机器上开启 <code>shell_escape</code>。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_7-1-makefile-自动化" tabindex="-1"><a class="header-anchor" href="#_7-1-makefile-自动化" aria-hidden="true">#</a> 7.1 Makefile 自动化</h3><p>用 Makefile 固化&quot;清理→编译→查看&quot;的完整流程，并利用依赖关系只重编发生变化的文件：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile —— 在项目根目录</span>
OUTDIR   <span class="token operator">:=</span> build
TEX      <span class="token operator">:=</span> main.tex
PDF      <span class="token operator">:=</span> <span class="token variable">$</span><span class="token punctuation">(</span>OUTDIR<span class="token punctuation">)</span>/main.pdf
TECTONIC <span class="token operator">:=</span> tectonic

<span class="token builtin-target builtin">.PHONY</span><span class="token punctuation">:</span> all clean watch open

<span class="token target symbol">all</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>PDF<span class="token punctuation">)</span>

<span class="token comment"># 编译 PDF（依赖所有 .tex 与 .bib，有改动才重建）</span>
<span class="token target symbol"><span class="token variable">$</span>(PDF)</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>TEX<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">wildcard</span> chapters/*.tex<span class="token punctuation">)</span> refs.bib
	<span class="token variable">$</span><span class="token punctuation">(</span>TECTONIC<span class="token punctuation">)</span> --compile-all --outdir <span class="token variable">$</span><span class="token punctuation">(</span>OUTDIR<span class="token punctuation">)</span> <span class="token variable">$</span><span class="token punctuation">(</span>TEX<span class="token punctuation">)</span>

<span class="token comment"># 监听源码变化自动重编译（需安装 watchexec）</span>
<span class="token target symbol">watch</span><span class="token punctuation">:</span>
	watchexec -w . --exts tex,bib make all

<span class="token target symbol">open</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>PDF<span class="token punctuation">)</span>
	open <span class="token variable">$</span><span class="token punctuation">(</span>PDF<span class="token punctuation">)</span>

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	rm -rf <span class="token variable">$</span><span class="token punctuation">(</span>OUTDIR<span class="token punctuation">)</span> *.log
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-github-actions-ci-集成" tabindex="-1"><a class="header-anchor" href="#_7-2-github-actions-ci-集成" aria-hidden="true">#</a> 7.2 GitHub Actions CI 集成</h3><p>tectonic 无需安装 TeX Live，是 CI 的绝配。<code>pkgforge/tectonic</code> 等社区 Docker 镜像已内置可用二进制。真实可用的 GitHub Actions 工作流：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/build.yml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> build<span class="token punctuation">-</span>pdf
<span class="token key atrule">on</span><span class="token punctuation">:</span>
  <span class="token key atrule">push</span><span class="token punctuation">:</span>
  <span class="token key atrule">workflow_dispatch</span><span class="token punctuation">:</span>

<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">build</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4

      <span class="token comment"># 安装 tectonic</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> wtfjoke/setup<span class="token punctuation">-</span>tectonic@v3

      <span class="token comment"># 用 actions/cache 持久化缓存，实现跨构建离线加速</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Cache tectonic
        <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/cache@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">path</span><span class="token punctuation">:</span> ~/.cache/Tectonic
          <span class="token key atrule">key</span><span class="token punctuation">:</span> tectonic<span class="token punctuation">-</span>$<span class="token punctuation">{</span><span class="token punctuation">{</span> hashFiles(&#39;main.tex&#39;) <span class="token punctuation">}</span><span class="token punctuation">}</span>

      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Compile
        <span class="token key atrule">run</span><span class="token punctuation">:</span> tectonic <span class="token punctuation">-</span><span class="token punctuation">-</span>compile<span class="token punctuation">-</span>all <span class="token punctuation">-</span><span class="token punctuation">-</span>outdir dist main.tex

      <span class="token comment"># 上传 PDF 为构建产物</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/upload<span class="token punctuation">-</span>artifact@v4
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">name</span><span class="token punctuation">:</span> main<span class="token punctuation">-</span>pdf
          <span class="token key atrule">path</span><span class="token punctuation">:</span> dist/main.pdf
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-3-批量处理脚本" tabindex="-1"><a class="header-anchor" href="#_7-3-批量处理脚本" aria-hidden="true">#</a> 7.3 批量处理脚本</h3><p>对同一目录下多个文档做批量编译，用循环脚本即可：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token comment"># batch-build.sh —— 批量编译 ./docs 下所有 .tex</span>
<span class="token builtin class-name">set</span> <span class="token parameter variable">-euo</span> pipefail
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> dist

<span class="token keyword">for</span> <span class="token for-or-select variable">tex</span> <span class="token keyword">in</span> docs/*.tex<span class="token punctuation">;</span> <span class="token keyword">do</span>
  <span class="token assign-left variable">name</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">basename</span> <span class="token string">&quot;<span class="token variable">$tex</span>&quot;</span> .tex<span class="token variable">)</span></span>&quot;</span>
  <span class="token builtin class-name">echo</span> <span class="token string">&quot;==&gt; 编译 <span class="token variable">$name</span>&quot;</span>
  tectonic --compile-all <span class="token parameter variable">--outdir</span> <span class="token string">&quot;dist/<span class="token variable">$name</span>&quot;</span> <span class="token string">&quot;<span class="token variable">$tex</span>&quot;</span>
<span class="token keyword">done</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;全部完成，产物位于 dist/&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-4-与-pandoc-搭配-markdown-→-高质量-latex-pdf" tabindex="-1"><a class="header-anchor" href="#_7-4-与-pandoc-搭配-markdown-→-高质量-latex-pdf" aria-hidden="true">#</a> 7.4 与 pandoc 搭配：Markdown → 高质量 LaTeX/PDF</h3><p>写作用 Markdown、出版用 LaTeX 是常见工作流。pandoc 把 Markdown 转成 tectonic 可直接编译的 LaTeX，再交给 tectonic 出 PDF：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># Markdown 转 LaTeX（用 citeproc 处理参考文献）</span>
pandoc report.md <span class="token punctuation">\\</span>
  <span class="token parameter variable">--citeproc</span> <span class="token parameter variable">--bibliography</span><span class="token operator">=</span>refs.bib <span class="token parameter variable">--csl</span><span class="token operator">=</span>chicago-author-date.csl <span class="token punctuation">\\</span>
  <span class="token parameter variable">-o</span> report.tex

<span class="token comment"># 再由 tectonic 编译出 PDF</span>
tectonic --compile-all <span class="token parameter variable">--outdir</span> dist report.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>若想完全避开 LaTeX 依赖，也可让 pandoc 配合任意 LaTeX 引擎直接出 PDF，但使用 tectonic 可保证服务器端无需装 TeX Live。</p><h3 id="_7-5-与-latexindent-搭配-代码格式统一" tabindex="-1"><a class="header-anchor" href="#_7-5-与-latexindent-搭配-代码格式统一" aria-hidden="true">#</a> 7.5 与 latexindent 搭配：代码格式统一</h3><p>用 <code>latexindent</code> 统一多章源码的缩进与格式，再交给 tectonic 编译，适合多人协作保持风格一致：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装（macOS 通过 Homebrew 或 TeX Live）</span>
brew <span class="token function">install</span> latexindent   <span class="token comment"># 或: perl cpanm -i latexindent</span>

<span class="token comment"># 批量格式化所有章节</span>
latexindent <span class="token parameter variable">-w</span> chapters/*.tex main.tex

<span class="token comment"># 再编译</span>
tectonic --compile-all <span class="token parameter variable">--outdir</span> dist main.tex
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>latexindent 的规则可用 <code>latexindent.yaml</code> 定制（见 latexindent 专题教程），配合 <code>.pre-commit</code> 或 CI 可实现「提交前自动格式化」。</p><h3 id="_7-6-生产级实践要点" tabindex="-1"><a class="header-anchor" href="#_7-6-生产级实践要点" aria-hidden="true">#</a> 7.6 生产级实践要点</h3><ul><li><strong>版本锁定</strong>：在 CI 或 Docker 中固定 tectonic 版本（如 <code>brew install tectonic@0.15</code> 或固定镜像 tag），避免上游更新导致行为漂移。</li><li><strong>目录隔离</strong>：始终用 <code>--outdir</code>/<code>output_dir</code> 把产物与中间文件集中，<code>.gitignore</code> 掉 <code>build/</code>、<code>dist/</code>、<code>*.log</code>、<code>*.aux</code>，只提交源码与 <code>.bib</code>。</li><li><strong>缓存即资产</strong>：把缓存目录纳入 CI 缓存或私有镜像，让离线/内网环境也能秒级编译。</li><li><strong>不可信输入</strong>：默认关闭 <code>shell_escape</code>；对用户上传或外部来源的 <code>.tex</code> 单独沙箱编译。</li><li><strong>多遍必开</strong>：凡涉及目录/引用/文献的大文档，CI 里固定加 <code>--compile-all</code>，防止「本地 OK、CI 缺遍」的编号错乱。</li></ul><h3 id="_7-7-x-实验性命令体系-大型项目的工作流入口" tabindex="-1"><a class="header-anchor" href="#_7-7-x-实验性命令体系-大型项目的工作流入口" aria-hidden="true">#</a> 7.7 <code>-X</code> 实验性命令体系：大型项目的工作流入口</h3><p>tectonic 0.15 起引入了一套<strong>实验性（experimental）子命令体系</strong>，统一入口为 <code>tectonic -X</code>。它把「创建项目 → 编译 → 监听 → 管理资源」整合成一套工程化工作流，<strong>特别适合大型 LaTeX 项目</strong>。用 <code>tectonic -X --help</code> 可列出全部子命令：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tectonic <span class="token parameter variable">-X</span>          <span class="token comment"># 列出所有实验性子命令</span>
<span class="token comment"># build / bundle / compile / dump / init / new / show / watch</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>以下是在大型项目中常用的几个：</p><h4 id="_1-tectonic-x-new-与-x-init-创建标准项目骨架" tabindex="-1"><a class="header-anchor" href="#_1-tectonic-x-new-与-x-init-创建标准项目骨架" aria-hidden="true">#</a> ① <code>tectonic -X new</code> 与 <code>-X init</code>：创建标准项目骨架</h4><p><code>-X new</code> 在当前目录生成一个带 <code>Tectonic.toml</code> 配置和 <code>main.tex</code> 入口的完整项目骨架，是<strong>大型项目管理的基础</strong>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 创建一个名为 thesis 的新项目目录</span>
tectonic <span class="token parameter variable">-X</span> new thesis
<span class="token builtin class-name">cd</span> thesis
<span class="token comment"># 生成的内容包括 Tectonic.toml 与默认 main.tex</span>

<span class="token comment"># 或在当前空目录初始化</span>
tectonic <span class="token parameter variable">-X</span> init
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>项目根下的 <code>Tectonic.toml</code> 集中管理编译行为（输出目录、编译遍数、shell 转义开关等），比每次都敲一堆命令行参数更利于团队协作与 CI 复用。</p><h4 id="_2-tectonic-x-watch-监听源文件变化自动编译" tabindex="-1"><a class="header-anchor" href="#_2-tectonic-x-watch-监听源文件变化自动编译" aria-hidden="true">#</a> ② <code>tectonic -X watch</code>：监听源文件变化自动编译</h4><p>写大型文档时，<code>-X watch</code> 会<strong>监听所有输入文件（含子章节、<code>.bib</code>、图片）的变化并自动重新编译</strong>，省去手动触发。适合与编辑器分屏实时预览 PDF：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 默认监听并执行 build</span>
tectonic <span class="token parameter variable">-X</span> <span class="token function">watch</span>

<span class="token comment"># 监听时指定要执行的命令（默认是 build）</span>
tectonic <span class="token parameter variable">-X</span> <span class="token function">watch</span> <span class="token parameter variable">-x</span> build --keep-logs <span class="token parameter variable">--open</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>配合 <code>--open</code> 每次编译完自动用系统 PDF 查看器打开，实现「改一下 → 自动刷新」的即时反馈循环。</p><h4 id="_3-tectonic-x-build-在项目内构建文档" tabindex="-1"><a class="header-anchor" href="#_3-tectonic-x-build-在项目内构建文档" aria-hidden="true">#</a> ③ <code>tectonic -X build</code>：在项目内构建文档</h4><p>在 <code>-X new</code> 建好的项目里，用 <code>-X build</code> 代替手写 <code>tectonic main.tex</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tectonic <span class="token parameter variable">-X</span> build                 <span class="token comment"># 按 Tectonic.toml 构建</span>
tectonic <span class="token parameter variable">-X</span> build --keep-logs     <span class="token comment"># 保留日志便于排错</span>
tectonic <span class="token parameter variable">-X</span> build <span class="token parameter variable">--open</span>          <span class="token comment"># 构建后自动打开 PDF</span>
tectonic <span class="token parameter variable">-X</span> build --only-cached   <span class="token comment"># 只用本地缓存资源（离线构建）</span>
tectonic <span class="token parameter variable">-X</span> build <span class="token parameter variable">--untrusted</span>     <span class="token comment"># 把文档当不可信输入，关闭不安全特性</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>--only-cached</code> 对离线/内网环境很有用；<code>--untrusted</code> 对编译外部来源文档更安全。</p><h4 id="_4-tectonic-x-bundle-与-x-dump-管理文件包与中间产物" tabindex="-1"><a class="header-anchor" href="#_4-tectonic-x-bundle-与-x-dump-管理文件包与中间产物" aria-hidden="true">#</a> ④ <code>tectonic -X bundle</code> 与 <code>-X dump</code>：管理文件包与中间产物</h4><ul><li><code>tectonic -X bundle search 关键词</code>：在项目资源包中按名字过滤文件，排查某宏包/字体是否可用。</li><li><code>tectonic -X bundle cat 文件名</code>：直接查看包内某文件的原始内容，便于检查缓存的格式定义。</li><li><code>tectonic -X dump &lt;文件名&gt;</code>：执行一次<strong>部分编译</strong>并输出某个中间文件（如 <code>.aux</code>、<code>.log</code>、<code>.toc</code>），用于排查目录/引用编号问题。</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 查看项目里是否包含某字体/宏包</span>
tectonic <span class="token parameter variable">-X</span> bundle search .bib
<span class="token comment"># 输出生成的 .aux 看交叉引用辅助信息</span>
tectonic <span class="token parameter variable">-X</span> dump main.aux
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h4 id="_5-tectonic-x-show-查看环境信息" tabindex="-1"><a class="header-anchor" href="#_5-tectonic-x-show-查看环境信息" aria-hidden="true">#</a> ⑤ <code>tectonic -X show</code>：查看环境信息</h4><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>tectonic <span class="token parameter variable">-X</span> show user-cache-dir   <span class="token comment"># 打印默认缓存目录路径</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>配合 <code>TECTONIC_CACHE_DIR</code> 环境变量，可在脚本里动态获取并持久化缓存位置。</p><blockquote><p>⚠️ <strong>注意</strong>：<code>-X</code> 命令体系处于<strong>实验阶段</strong>，接口和参数在后续版本可能调整。跨版本升级后请以 <code>tectonic -X --help</code> 及各子命令 <code>--help</code> 的实际输出为准，勿在关键 CI 中依赖尚未稳定的行为。</p></blockquote>`,120),i=[c];function o(d,l){return e(),a("div",null,i)}const u=n(t,[["render",o],["__file","tectonic.html.vue"]]);export{u as default};
